const MAX_ROWS = 50;
const MAX_CHARS = 12000;
const all = items.map((i) => i.json);
const sample = all.slice(0, MAX_ROWS);
let text = JSON.stringify(sample, null, 2);
if (text.length > MAX_CHARS) text = text.slice(0, MAX_CHARS) + '\n...[truncated]';

let instruction = '';
try {
  const v = $('规范化表单表格').first().json.instruction;
  if (v) instruction = String(v).trim();
} catch (e) {}

const prompt = [
  '你是表格解析助手，面向普通人阅读。',
  '下面是表格文件转成的 JSON 行数据（可能来自 xlsx/xls/csv）。',
  '请用简体中文输出「纯文本报告」，不要输出 JSON，不要使用 markdown 代码围栏，不要输出思考过程。',
  '根据表格真实内容灵活组织，不要套固定发票模板。',
  '建议结构（按需取舍）：',
  '',
  '【解析结果】',
  '表格概要：…',
  '主要字段：…',
  '数据条数：…',
  '要点：…',
  '明细摘要：…',
  '',
  instruction ? ('用户补充说明（请重点关注）：' + instruction) : '',
  'DATA:',
  text,
].filter(Boolean).join('\n');

return [{ json: { rowCount: all.length, sampleCount: sample.length, instruction, prompt } }];

