  .replace(/^[\s\S]*?<\/think>/i, '')
  .replace(/<think>[\s\S]*?<\/think>/ig, '')
  .replace(/```[a-zA-Z]*\n?/g, '')
  .replace(/```/g, '')
  .trim();
