if (!readableText.includes('【解析结果】')) readableText = '【解析结果】\n' + readableText;
const readableHtml = '<div style="white-space:pre-wrap;font-family:system-ui,sans-serif;font-size:16px;line-height:1.7;">'
  + readableText.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>')
  + '</div>';
return [{ json: { report: readableText, readableText, readableHtml, modelRaw: content, usage: resp.usage || null, model: resp.model || null } }];

const item = items[0];
if (!item.binary || !item.binary.data) {
  throw new Error('FMT_INVALID: 缺少图片 binary.data，请从表单上传图片。');
}
const meta = item.binary.data;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');

function detectFmt(buf) {
  if (!buf || buf.length < 12) return 'bin';
  if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'jpg';
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) return 'png';
  if (buf[0] === 0x47 && buf[1] === 0x49 && buf[2] === 0x46) return 'gif';
  if (buf[0] === 0x52 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x46
      && buf[8] === 0x57 && buf[9] === 0x45 && buf[10] === 0x42 && buf[11] === 0x50) return 'webp';
  if (buf[0] === 0x77 && buf[1] === 0x78 && buf[2] === 0x67 && buf[3] === 0x66) return 'wxgf';
  if (buf[0] === 0x00 && buf[1] === 0x00 && buf[2] === 0x00 && buf[3] === 0x01) return 'hevc';
  if (buf[0] === 0x00 && buf[1] === 0x00 && buf[2] === 0x01) return 'hevc';
  if (buf[0] === 0x42 && buf[1] === 0x4d) return 'bmp';
  return 'bin';
}
const MIME = { jpg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp' };
const fmt = detectFmt(buf);
if (!MIME[fmt]) {
  throw new Error(
    'FMT_INVALID: 图片魔数不是 JPEG/PNG/GIF/WEBP（检测为 ' + fmt + '，声称 mime='
    + (meta.mimeType || '') + '，字节=' + buf.length
    + '）。模型无法识别。请确认微信监控已把 HEVC/wxgf 转成 JPEG 后重发。'
  );
}
const mime = MIME[fmt];
const b64 = buf.toString('base64');
if (!b64 || b64.length < 32) {
  throw new Error('FMT_INVALID: 读取图片二进制失败（base64 过短）。');
}
const dataUrl = 'data:' + mime + ';base64,' + b64;
const extra = (item.json.instruction || '').toString().trim();

const prompt = [
  '你是通用图片理解助手。用户可能上传截图、照片、说明书页、风景、设计稿等，不要预设题型。',
  '即使图片看起来像票据，也只用简洁中文写「看见了什么」。',
  '硬性要求：',
  '1) 不要假设是发票/收据/合同；不要编造公司名、发票号、金额字段。',
  '2) 没有的信息就省略该段落，不要写「未识别」。',
  '3) 不要输出 JSON；不要使用 markdown 代码围栏；不要写思考过程。',
  '4) 可见文字尽量忠实摘录；看不清就注明看不清，不要编造。',
  '5) 用简体中文字段；必要时使用列表，不要时使用。',
  '请按下列结构：',
  '图片类型：',
  '内容概述：',
  '可见文字：',
  '关键信息：',
  '其他细节：',
