  ? rawName.replace(/\.(hevc|bin|dat|wxgf|bmp)$/i, '.' + ext)
  : (rawName.includes('.') ? rawName : rawName + '.' + ext);

return [{
  json: {
    source: item.json.source || meta.fileName || 'image',
    instruction: extra,
    mimeType: mime,
    bytes: buf.length,
