      if (val == null) return;
      if (Array.isArray(val)) {
        const t = val.map((x) => (typeof x === 'string' ? x : JSON.stringify(x))).filter(Boolean).join('\n');
        if (t) lines.push(label + '：\n' + t);
      } else if (typeof val === 'object') {
        const entries = Object.entries(val).filter(([, v]) => v != null && String(v).trim() !== '');
        if (entries.length) {
          lines.push(label + '：');
          for (const [k, v] of entries) lines.push('- ' + k + '：' + v);
        }
      } else if (String(val).trim() !== '') {
        lines.push(label + '：' + String(val));
      }
    };

    // Generic mappings only
    pushKV('图片类型', obj.image_type || obj.type || obj.category || obj['图片类型']);
    pushKV('内容概述', obj.summary || obj.overview || obj.description || obj['内容概述'] || obj['摘要']);
    pushKV('可见文字', obj.texts || obj.ocr || obj.text || obj['可见文字']);
    pushKV('关键信息', obj.fields || obj.key_info || obj.info || obj['关键信息']);
    pushKV('其他细节', obj.insights || obj.details || obj.notes || obj['其他细节'] || obj['备注']);

    // Any other top-level keys not already used
    const used = new Set(['image_type','type','category','图片类型','summary','overview','description','内容概述','摘要','texts','ocr','text','可见文字','fields','key_info','info','关键信息','insights','details','notes','其他细节','备注']);
    for (const [k, v] of Object.entries(obj)) {
      if (used.has(k)) continue;
      pushKV(k, v);
    }

    if (lines.length > 1) readableText = lines.join('\n');
  }
} catch (e) {}

readableText = String(readableText).trim();
if (!readableText.startsWith('【识别结果】')) {
  readableText = '【识别结果】\n' + readableText;
