const raw = items[0].json || {};
const itemError = items[0].error;
const exec = raw.execution || {};

function formatErr(val) {
  if (val == null || val === '') return '';
  if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
    const s = String(val).trim();
    return s === '[object Object]' ? '' : s;
  }
  if (typeof val === 'object') {
    if (val.message) return formatErr(val.message) || formatErr(val.description) || formatErr(val.error);
    if (val.error && val.error !== val) return formatErr(val.error);
    try { return JSON.stringify(val).slice(0, 160); } catch (e) { return ''; }
  }
  return String(val);
}

function classify(msg) {
  const s = String(msg || '');
  if (/FMT_NO_FFMPEG/i.test(s)) return 'FMT_NO_FFMPEG';
  if (/FMT_INVALID|魔数|wxgf|HEVC|不是 JPEG|格式无法|invalid.?image|unsupported.?image/i.test(s)) return 'FMT_INVALID';
  if (/429|rate.?limit|too many requests|限流/i.test(s)) return 'MODEL_RATE_LIMIT';
  if (/ECONNREFUSED|8787|append_api|写表服务/i.test(s)) return 'APPEND_DOWN';
  if (/DECRYPT|解密失败|AES/i.test(s)) return 'DECRYPT_FAIL';
  if (/Minimax:/i.test(s) && /DeepSeek:/i.test(s)) return 'MODEL_BOTH_FAIL';
  return 'UNKNOWN';
}

const nodeErr = (typeof itemError === 'object' && itemError) || (typeof raw.error === 'object' && raw.error) || (typeof exec.error === 'object' && exec.error) || {};
let msg = formatErr(itemError && itemError.message) || formatErr(nodeErr.message) || formatErr(nodeErr.description) || formatErr(raw.message) || formatErr(itemError) || formatErr(raw.error) || '未知错误';
if (!msg || msg === '[object Object]') msg = '未知错误';

try {
