  for (const name of names) {
    try {
      if (!$(name).isExecuted) continue;
      const it = $(name).first();
      if (it && it.binary && it.binary.data) {
        return { data: it.binary.data };
      }
    } catch (e) {}
  }
  return undefined;
}
const binary = pickBinary();
const out = {
  json: {
    telegramText: short,
    readableText: short,
    report: short,
    lastNode,
    errorMessage: String(msg),
    errorCode: code,
